import React from "react";
import { FEATURES } from "./Content";
import { Sparkles, Ruler, PackageOpen, Truck, Gem, ShieldCheck } from "lucide-react";

const icons = [Sparkles, Ruler, PackageOpen, Truck, Gem, ShieldCheck];

export default function WhyChooseUs() {
  return (
    <section id="why" className="relative px-6 md:px-12 lg:px-24 py-24 md:py-32">
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-10 mb-12">
        <div className="lg:col-span-5">
          <div className="overline mb-4">Why D Sajawat</div>
          <h2 className="serif" style={{ fontSize: "clamp(36px, 5vw, 72px)", lineHeight: 1.02, fontWeight: 300, color: "#fffff0" }}>
            Built for <span style={{ color: "#d4af37", fontStyle: "italic" }}>professionals</span> who care about finish.
          </h2>
        </div>
        <p className="lg:col-span-6 lg:col-start-7 max-w-xl" style={{ color: "rgba(255,255,240,0.65)", lineHeight: 1.7 }}>
          Six promises that have kept India's most demanding decorators coming back. From custom sizing to nationwide logistics - we keep your event on schedule and on style.
        </p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
        {FEATURES.map((f, i) => {
          const Icon = icons[i % icons.length];
          return (
            <div key={f.title} className="glass gold-border rounded-sm p-7 transition-all duration-500 hover:translate-y-[-4px]" style={{ minHeight: 200 }}>
              <div className="w-12 h-12 rounded-sm flex items-center justify-center mb-5" style={{ background: "linear-gradient(135deg, rgba(212,175,55,0.18), rgba(247,231,206,0.05))", border: "1px solid rgba(212,175,55,0.4)" }}>
                <Icon size={22} strokeWidth={1.4} color="#d4af37" />
              </div>
              <h3 className="serif mb-2" style={{ fontSize: 24, color: "#fffff0", fontWeight: 400 }}>{f.title}</h3>
              <p style={{ color: "rgba(255,255,240,0.65)", fontSize: 14, lineHeight: 1.6 }}>{f.desc}</p>
            </div>
          );
        })}
      </div>
    </section>
  );
}
